mapper.select:
SELECT 
FROM pairing p
JOIN coffee_log c ON c.coffee_log_id = p.coffee_log_id
JOIN music_log m ON m.music_log_id = p.music_log_id
WHERE p.pairing_id = #{pairingId}
  AND p.member_id = #{memberId}

mapper.insert:
INSERT INTO pairing (
  member_id, coffee_log_id, music_log_id, mood_summary, mood_tags,
  pairing_score, pairing_text, ai_reason
)
VALUES (
  #{memberId}, #{coffeeLogId}, #{musicLogId}, #{moodSummary}, #{moodTags},
  #{pairingScore}, #{pairingText}, #{aiReason}
)

mapper.delete:
DELETE FROM pairing
WHERE pairing_id = #{pairingId}
  AND member_id = #{memberId}
